package com.portfolio;
import com.portfolio.config.ErrorLoggingService; import com.portfolio.domain.*; import com.portfolio.repository.*; import com.portfolio.service.*; import org.junit.jupiter.api.*; import org.mockito.*; import java.math.BigDecimal; import java.time.LocalDate; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.any; import static org.mockito.Mockito.*;
class PortfolioTransactionServiceTest {
 @Mock PortfolioRepository portfolios; @Mock TransactionRepository transactions; @Mock AuditLogRepository audits; @Mock ErrorLoggingService errors; PortfolioTransactionService service; Portfolio portfolio;
 @BeforeEach void setUp(){MockitoAnnotations.openMocks(this);service=new PortfolioTransactionService(portfolios,transactions,audits,errors,new PortfolioValidationService());portfolio=new Portfolio();portfolio.setPortfolioId("PORT0001");portfolio.setAccountNo("1234567890");portfolio.setTotalUnits(new BigDecimal("10.0000"));portfolio.setTotalCost(new BigDecimal("100.00"));when(portfolios.findById("PORT0001")).thenReturn(java.util.Optional.of(portfolio));when(transactions.save(any())).thenAnswer(i->i.getArgument(0));when(portfolios.save(any())).thenAnswer(i->i.getArgument(0));}
 private Transaction tx(TransactionType type,BigDecimal qty,BigDecimal price,BigDecimal amount){Transaction t=new Transaction();t.setTransactionId("id");t.setPortfolioId("PORT0001");t.setTransactionType(type);t.setQuantity(qty);t.setPrice(price);t.setAmount(amount);t.setTransactionDate(LocalDate.now());return t;}
 @Test void buy(){service.process(tx(TransactionType.BUY,new BigDecimal("2"),new BigDecimal("10"),new BigDecimal("20")));assertEquals(new BigDecimal("12.0000"),portfolio.getTotalUnits());assertEquals(new BigDecimal("120.00"),portfolio.getTotalCost());}
 @Test void insufficientSell(){BusinessException e=assertThrows(BusinessException.class,()->service.process(tx(TransactionType.SELL,new BigDecimal("11"),BigDecimal.ONE,BigDecimal.TEN)));assertEquals("Insufficient units for sale",e.getMessage());}
 @Test void sell(){service.process(tx(TransactionType.SELL,new BigDecimal("2"),BigDecimal.ONE,new BigDecimal("20")));assertEquals(new BigDecimal("8.0000"),portfolio.getTotalUnits());}
 @Test void fee(){service.process(tx(TransactionType.FEE,BigDecimal.ONE,BigDecimal.ONE,new BigDecimal("5")));assertEquals(new BigDecimal("95.00"),portfolio.getTotalCost());}
 @Test void transfer(){assertThrows(UnsupportedOperationException.class,()->service.process(tx(TransactionType.TRANSFER,BigDecimal.ONE,BigDecimal.ZERO,BigDecimal.ZERO)));}
 @Test void amountValidation(){assertThrows(BusinessException.class,()->service.validateAmounts(tx(TransactionType.BUY,BigDecimal.ZERO,BigDecimal.ONE,BigDecimal.ONE)));assertThrows(BusinessException.class,()->service.validateAmounts(tx(TransactionType.BUY,BigDecimal.ONE,BigDecimal.ZERO,BigDecimal.ONE)));assertThrows(BusinessException.class,()->service.validateAmounts(tx(TransactionType.BUY,BigDecimal.ONE,BigDecimal.ONE,BigDecimal.ZERO)));assertDoesNotThrow(()->service.validateAmounts(tx(TransactionType.TRANSFER,BigDecimal.ONE,BigDecimal.ZERO,BigDecimal.ZERO)));}
}
